#include "unity.h"
#include "xy_lis2dw12.h"
#include <string.h>
static xy_error_t er;static uint8_t raw[6]={0x00,0x10,0x00,0xF0,0x00,0x08};
xy_error_t xy_i2c_device_init(xy_i2c_device_t*d,void*h,uint16_t a,uint32_t t){memset(d,0,sizeof(*d));d->base.initialized=1;d->i2c_handle=h;d->dev_addr=a;d->timeout=t;return 0;}xy_error_t xy_i2c_device_read_reg(xy_i2c_device_t*d,uint8_t r,uint8_t*b,size_t n){TEST_ASSERT_TRUE(d->base.initialized);if(er)return er;if(r==XY_LIS2DW12_REG_WHO_AM_I)*b=XY_LIS2DW12_WHO_AM_I;else memcpy(b,raw,n);return 0;}xy_error_t xy_i2c_device_write_reg(xy_i2c_device_t*d,uint8_t r,const uint8_t*b,size_t n){(void)r;(void)b;(void)n;TEST_ASSERT_TRUE(d->base.initialized);return er;}void xy_device_delay_ms(uint32_t ms){(void)ms;} void xy_hal_delay_ms(uint32_t ms){TEST_ASSERT_EQUAL_UINT32(10,ms);}uint32_t xy_hal_sys_get_tick_count(void){return 77;}void setUp(void){er=0;}void tearDown(void){}
static void ok(void){xy_lis2dw12_t d;xy_lis2dw12_sample_t s;int bus;TEST_ASSERT_EQUAL_INT(0,xy_lis2dw12_init(&d,&bus));TEST_ASSERT_EQUAL_UINT16(XY_LIS2DW12_ADDR,d.i2c_dev.dev_addr);TEST_ASSERT_EQUAL_INT(0,xy_lis2dw12_read(&d,&s));TEST_ASSERT_EQUAL_INT16(256,s.raw_x);TEST_ASSERT_EQUAL_INT16(-256,s.raw_y);TEST_ASSERT_EQUAL_INT32(499,s.x_mg);TEST_ASSERT_EQUAL_INT32(-499,s.y_mg);TEST_ASSERT_EQUAL_UINT32(77,s.timestamp);TEST_ASSERT_EQUAL_INT(0,xy_lis2dw12_deinit(&d));}static void fail(void){xy_lis2dw12_t d;xy_lis2dw12_sample_t s={1,2,3,4,5,6,7};int bus;TEST_ASSERT_EQUAL_INT(0,xy_lis2dw12_init(&d,&bus));d.sample=s;er=XY_DEVICE_TIMEOUT;TEST_ASSERT_EQUAL_INT(XY_DEVICE_TIMEOUT,xy_lis2dw12_read(&d,&s));TEST_ASSERT_EQUAL_INT16(1,s.raw_x);d.i2c_dev.base.initialized=0;TEST_ASSERT_EQUAL_INT(XY_DEVICE_INVALID_PARAM,xy_lis2dw12_read(&d,&s));}int main(void){UNITY_BEGIN();RUN_TEST(ok);RUN_TEST(fail);return UNITY_END();}
